#!/usr/bin/env bash
# Run the window checker (and the prompt 03 statistics/render) on every window generated by windows.sh.
#   tools/worldscan/checkall.sh <tag> save    save the surface heights as the reference (the dune-only run)
#   tools/worldscan/checkall.sh <tag> cmp     compare with the saved reference tag "base"
# Output: docs/continents/<tag>_<name>_s<seed>.{png,json} (render) and ..._check.json (window checker), summary on stdout.
set -e
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"; cd "$ROOT"
TAG=$1; MODE=$2; mkdir -p build/worldscan docs/continents
grep -v '^#' tools/worldscan/windows.tsv | while IFS=$'\t' read -r name seed cx cz note; do
  [ -z "$name" ] && continue
  [[ -n "$ONLY" && "$name" != *$ONLY* ]] && continue
  x0=$(( (cx - 512) / 16 * 16 )); z0=$(( (cz - 512) / 16 * 16 ))
  [ $(( (cx - 512) % 16 )) -lt 0 ] && x0=$(( x0 - 16 )); [ $(( (cz - 512) % 16 )) -lt 0 ] && z0=$(( z0 - 16 ))
  W="${TAG}_${name}_s${seed}"; R="run-server/$W/dimensions/islandcraft_dunesofarrakis/arrakis/region"
  M="build/worldscan/cmask_${name}_s${seed}.bin"; ./tools/worldscan/coast.sh src/main/resources/data/islandcraft_dunesofarrakis/arrakis/continents.json mask $seed $x0 $z0 1024 "$M" >/dev/null
  H="build/worldscan/heights_${W}.i16"; EXTRA=""
  [ "$MODE" = save ] && EXTRA="--save $H"
  if [ "$MODE" = cmp ]; then B="build/worldscan/heights_base_${name}_s${seed}.i16"; if [ -f "$B" ]; then EXTRA="--baseline $B --save $H"; else EXTRA="--save $H"; fi; fi
  case "$name" in
    gap_purple_blue) P="1 3";; gap_purple_brown) P="1 4";; gap_green_blue) P="2 3";; gap_purple_green) P="1 2";; *) P="";;
  esac
  if [ -n "$P" ]; then L=$(node -e 'const g=require("./docs/continents/gaps.json");const [a,b]=process.argv[1].split(" ").map(Number);const e=g.find(e=>e.a===a&&e.b===b);console.log(`${e.ax},${e.az},${e.bx},${e.bz}`)' "$P"); EXTRA="$EXTRA --line $L"; fi
  echo "=== $W (x0 $x0 z0 $z0)"
  node tools/worldscan/windowcheck.js "$R" "$M" $x0 $z0 1024 "docs/continents/${W}_check" $EXTRA
  node tools/worldscan/render.js "$R" "docs/continents/${W}" $x0 $z0 1024 --scale 1 | grep -E "^height above|^columns at|^air|^crest direction|^chunk seams|^wrote" | cut -c1-210
done
